import pyomo.environ as pyo

DATA = {
    "I": list(range(1, 9)),          # distribution centers 1..8
    "J": list(range(1, 10)),         # retail stores 1..9
    "opening_cost": {
        1: 151000, 2: 192000, 3: 114000, 4: 171000,
        5: 160000, 6: 120000, 7: 182000, 8: 186000,
    },
    "capacity": {
        1: 1447, 2: 1886, 3: 1962, 4: 1392,
        5: 1191, 6: 1218, 7: 1088, 8: 1178,
    },
    "demand": {
        1: 779, 2: 892, 3: 440, 4: 556, 5: 414,
        6: 464, 7: 920, 8: 743, 9: 528,
    },
    "transport_cost": {
        1: {1: 3, 2: 3, 3: 5, 4: 4, 5: 3, 6: 5, 7: 2, 8: 4, 9: 2},
        2: {1: 4, 2: 5, 3: 1, 4: 4, 5: 2, 6: 5, 7: 4, 8: 1, 9: 1},
        3: {1: 3, 2: 3, 3: 2, 4: 4, 5: 4, 6: 3, 7: 4, 8: 4, 9: 1},
        4: {1: 3, 2: 5, 3: 3, 4: 5, 5: 1, 6: 2, 7: 4, 8: 1, 9: 4},
        5: {1: 2, 2: 2, 3: 1, 4: 2, 5: 5, 6: 2, 7: 4, 8: 4, 9: 4},
        6: {1: 4, 2: 5, 3: 3, 4: 1, 5: 4, 6: 2, 7: 4, 8: 2, 9: 2},
        7: {1: 4, 2: 5, 3: 2, 4: 2, 5: 4, 6: 2, 7: 2, 8: 4, 9: 4},
        8: {1: 1, 2: 5, 3: 5, 4: 2, 5: 5, 6: 2, 7: 1, 8: 4, 9: 4},
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["I"], ordered=True)
    model.J = pyo.Set(initialize=d["J"], ordered=True)

    # Opening decision for each distribution center
    model.y = pyo.Var(model.I, within=pyo.Binary)

    # Flow of units from center i to store j
    model.x = pyo.Var(model.I, model.J, within=pyo.NonNegativeReals)

    # Objective: opening costs + transportation costs (to be minimized)
    def obj_rule(m):
        return (
            sum(d["opening_cost"][i] * m.y[i] for i in m.I)
            + sum(d["transport_cost"][i][j] * m.x[i, j] for i in m.I for j in m.J)
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # (a) Demand satisfaction: sum of flows into store j equals its demand
    def demand_rule(m, j):
        return sum(m.x[i, j] for i in m.I) == d["demand"][j]

    model.demand_floor = pyo.Constraint(model.J, rule=demand_rule)

    # (b) Linking + capacity: flow out of center i cannot exceed capacity if opened
    def capacity_rule(m, i):
        return sum(m.x[i, j] for j in m.J) <= d["capacity"][i] * m.y[i]

    model.capacity_link = pyo.Constraint(model.I, rule=capacity_rule)

    return model
